/**
 * Returns a NEW array with the unique, finite numbers found in `values`,
 * sorted in ascending numeric order. The input is never mutated.
 *
 * - Non-number values (null, undefined, strings, objects, booleans) are dropped.
 * - NaN / Infinity / -Infinity are dropped (not finite).
 * - Duplicates are removed; -0 is normalized to 0.
 * - Sorting uses a numeric comparator (no locale dependence, no lexicographic order).
 *
 * @param {Array|Iterable} values
 * @returns {number[]}
 */
function uniqueSortedNumbers(values) {
  if (values == null) return [];
  if (typeof values[Symbol.iterator] !== 'function') return [];

  const seen = new Set();
  const result = [];

  for (const value of values) {
    // Only genuine finite numbers qualify.
    if (typeof value !== 'number') continue;
    if (!Number.isFinite(value)) continue; // rejects NaN, Infinity, -Infinity

    // Normalize -0 -> 0 so dedupe and ordering behave consistently.
    const n = value === 0 ? 0 : value;

    if (seen.has(n)) continue;

    seen.add(n);
    result.push(n);
  }

  // Ascending numeric order; never locale- or lexicography-dependent.
  result.sort((a, b) => a - b);

  return result;
}
