/**
 * Returns a new array containing only the finite numbers found in `values`,
 * deduplicated and sorted in ascending numeric order.
 *
 * - The input array is never mutated.
 * - Non-numbers, NaN, +Infinity and -Infinity are discarded.
 * - Sorting uses a numeric comparator (no locale-dependent default sort).
 *
 * @param {Array} values source values
 * @returns {number[]} new array of unique, finite, ascending numbers
 */
function uniqueSortedNumbers(values) {
  if (values === null || values === undefined) return [];

  // Support arrays and array-like objects without touching the source.
  const len = typeof values.length === 'number' ? values.length : 0;

  // --- 1. Collect finite numbers (order preserved, no mutation of input) ---
  const numbers = [];
  for (let i = 0; i < len; i++) {
    const v = values[i];
    if (typeof v === 'number' && Number.isFinite(v)) {
      numbers.push(v);
    }
  }

  // --- 2. Deduplicate with a plain null-prototype dictionary (O(n)) ---
  const seen = Object.create(null);
  const unique = [];
  for (let i = 0; i < numbers.length; i++) {
    const n = numbers[i];
    // String(-0) === "0", so -0 and 0 collapse into one entry.
    const key = String(n);
    if (seen[key] !== undefined || key in seen) continue;
    seen[key] = true;
    unique.push(n);
  }

  // --- 3. Sort numerically ascending (never locale/string dependent) ---
  unique.sort(function (a, b) {
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
  });

  return unique;
}
