# ──────────────────────────────────────────────
#  1. STRATEGY PATTERN — OS-Specific Logic
# ──────────────────────────────────────────────
class ApplicationKillerStrategy(ABC):
    """Abstract base for platform-specific closing logic."""

    @abstractmethod
    def is_system_process(self, proc: psutil.Process) -> bool:
        """Return True if the process must NOT be closed."""
        ...

    @abstractmethod
    def terminate(self, proc: psutil.Process) -> bool:
        """Try to close a single process. Return True on success."""
        ...

    @abstractmethod
    def get_user_apps(self) -> list:
        """Return list of (pid, name) for user-space GUI apps."""
        ...


# ──────────────────────────────────────────────
#  Windows Strategy
# ──────────────────────────────────────────────
class WindowsStrategy(ApplicationKillerStrategy):

    PROTECTED = {
        "system", "registry", "smss", "csrss", "wininit",
        "services", "lsass", "svchost", "explorer", "dngclient",
        "dwm", "audiodg", "fontdrvhost", "sihost", "taskhostw",
