        "device association framework", "cpl", "perfcounter",
        "codeintegrity", "sched", "nltest", "font",
    }

    def is_system_process(self, proc) -> bool:
        try:
            name = (proc.name() or "").lower()
            if name in self.PROTECTED:
                return True
            # Protect critical PIDs
            if proc.pid in (0, 1, 2, 3, 4):
                return True
            # Protect services (Windows service processes)
            if hasattr(proc, "create_time") and proc.create_time() < time.time() - 604800:
                # Running for > 1 week — likely OS core
                pass  # still allow — only check if it is a service
            return False
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            return True

