        except (psutil.NoSuchProcess, psutil.AccessDenied):
            return False

    def _enumerate_targets(self) -> list[tuple[int, str]]:
        """Return list of (pid, name) for processes safe to close."""
        targets = []
        # Prefer OS-reported GUI apps
        try:
            gui_apps = self.strategy.get_user_apps()
        except Exception:
